 "fields": {
  "parties": {
   "value": ["Northwind Labs, Inc.", "Kestrel Logistics Corp."],
   "quote": "Parties: (1) Northwind Labs, Inc. (\"Northwind\"); and (2) Kestrel Logistics Corp. (\"Kestrel\")."
  },
  "counterparty": {
   "value": "Kestrel Logistics Corp.",
   "quote": "Parties: (1) Northwind Labs, Inc. (\"Northwind\"); and (2) Kestrel Logistics Corp. (\"Kestrel\")."
  },
  "effective_date": {
   "value": "2025-01-16",
   "quote": "Effective Date: 16 January 2025"
  },
  "term_months": {
   "value": 24,
   "quote": "This Agreement shall commence on the Effective Date and continue for a period of 2 years."
  },
  "auto_renewal": {
   "value": true,
   "quote": "Upon expiration of the Initial Term, the Agreement renews automatically for additional twelve-month terms"
  },
  "renewal_notice_days": {
   "value": 30,
   "quote": "to opt out, a Party must notify the other no later than thirty days before the renewal date."
  },
  "governing_law": {
   "value": "Florida",
   "quote": "The laws of the State of Florida govern this Agreement and any dispute arising out of it."
  },
  "liability_cap": {
   "value": "fees_12m",
   "quote": "IN NO EVENT SHALL EITHER PARTY'S AGGREGATE LIABILITY ARISING OUT OF THIS AGREEMENT EXCEED THE TOTAL FEES PAID OR PAYABLE IN THE TWELVE (12) MONTHS PRECEDING THE EVENT GIVING RISE TO THE CLAIM."
  },
  "payment_terms_days": {
   "value": 90,
   "quote": "Payment terms are Net 90."
  },
  "contract_value": {
   "value": 24000,
   "quote": "The subscription fee is $24,000 per year, invoiced annually in advance."
  },
  "termination_for_convenience": {
   "value": false,
   "quote": "Either Party may terminate this Agreement only upon a material breach by the other Party that remains uncured thirty (30) days after written notice."
  },
  "confidentiality_years": {
   "value": null,
   "quote": null
  }
 },
 "signers": [
  {
   "name": "Dana Whitfield",
   "email": "dana@northwind.example",
   "title": "Chief Executive Officer",
   "party": "Northwind Labs, Inc."
  },
  {
   "name": "Samuel Okafor",
   "email": "samuel.okafor@kestrel.example",
   "title": "General Counsel",
   "party": "Kestrel Logistics Corp."
  }
 ],
 "risks": [
  {
   "id": "no_termination_for_convenience",
   "severity": "high",
   "message": "Northwind cannot exit the agreement without cause. It is locked in for the 2-year initial term and can only terminate for an uncured material breach.",
   "quote": "Either Party may terminate this Agreement only upon a material breach by the other Party that remains uncured thirty (30) days after written notice."
  },
  {
   "id": "auto_renewal_short_notice",
   "severity": "medium",
   "message": "The agreement renews automatically for 12-month terms unless notice is given at least 30 days before the renewal date. A missed deadline commits Northwind to another year at $24,000.",
   "quote": "the Agreement renews automatically for additional twelve-month terms; to opt out, a Party must notify the other no later than thirty days before the renewal date."
  },
  {
   "id": "no_confidentiality_clause",
   "severity": "medium",
   "message": "The agreement has no confidentiality provision, so Northwind's data shared with Kestrel is not contractually protected as confidential.",
   "quote": "Each Party shall comply with applicable anti-bribery, export control and sanctions laws, and shall promptly inform the other Party of any investigation that relates to this Agreement."
  },
  {
   "id": "mutual_liability_cap_fees_only",
   "severity": "low",
   "message": "Liability is capped at 12 months of fees (about $24,000) for both parties, with no carve-outs for data breach or confidentiality. Northwind's recovery for serious harm is limited.",
   "quote": "IN NO EVENT SHALL EITHER PARTY'S AGGREGATE LIABILITY ARISING OUT OF THIS AGREEMENT EXCEED THE TOTAL FEES PAID OR PAYABLE IN THE TWELVE (12) MONTHS PRECEDING THE EVENT GIVING RISE TO THE CLAIM."
  },
  {
   "id": "no_data_protection_terms",
   "severity": "low",
   "message": "As a SaaS agreement, it has no data protection, security or SLA terms. Only a general warranty of professional performance applies.",
   "quote": "Each Party warrants that it will perform its obligations in a professional and workmanlike manner"
  }
 ],
 "injection_attempt": false,
 "summary": "Northwind Labs, Inc. subscribes to Kestrel Logistics Corp.'s analytics platform for $24,000 per year, with a 2-year initial term starting 16 January 2025. It then renews automatically each year unless notice is given 30 days ahead, and Northwind can only terminate early for uncured breach."
}
